			title = "概述",
			text = [=[寒水村是{link:winterfall-furbolgs}寒水熊怪{/link}的家园，位于{link:everlook}永望镇{/link}以东的山中。这是一个满是小屋与图腾的地方，也是一个充满恐惧的地方。部族的大酋长在这里发号施令，信使们把一桶桶绿色{link:brewnall-village}烈酒{/link}从{link:felwood}费伍德森林{/link}运到这里。村里的{link:furbolgs}熊怪{/link}比他们从前的同类更高大、更凶猛。他们的萨满和熊人会攻击任何靠近的东西，无论是野兽还是旅人。]=],
