Translate("zhCN", "donova-snowden", {
	title = "多诺瓦·雪山",
	subtitle = "温泉学者",
	found = "冰火温泉旁",
	hint = "寻找在西部温泉旁扎营的学者。",
	allegiance = "林克与克拉兰克的朋友",
	aliases = { "多诺瓦" },
	sections = {
		{
			title = "概述",
			text = [=[多诺瓦·雪山来到{link:winterspring}冬泉谷{/link}，是为了探寻{link:frostfire-hot-springs}冰火温泉{/link}的秘密：在一片没有火山的土地上，温水却在冒着热气。她至今仍在温泉旁扎营。她耐心、好奇而善良，相信寒冷之地比任何温暖之地都藏着更多秘密。她的研究把她引向了一件比她预想的更黑暗的事：{link:winterfall-furbolgs}寒水熊怪{/link}的疯狂。]=],
		},
		{
			title = "意义",
			text = [=[多诺瓦是第一个追溯到{link:winterfall-furbolgs}寒水熊怪{/link}疯狂根源的人。通过她的研究，人们得知这个部族在饮用一种用{link:felwood}费伍德森林{/link}的腐化制成的{link:brewnall-village}烈酒{/link}，而温泉本身的热量也许来自恶魔。]=],
		},
		{
			title = "事迹",
			text = [=[• 她研究{link:frostfire-hot-springs}冰火温泉{/link}及其奇异的泉水。
• 她得知{link:winterfall-furbolgs}寒水熊怪{/link}利用温泉来净化他们的{link:brewnall-village}烈酒{/link}。
• 她发现了{link:darkwhisper-gorge}暗语峡谷{/link}的恶魔，并认为它们是温泉热量的来源。
• 她为朋友{link:linken}林克{/link}保管着一把剑，并知道如何完成它。]=],
		},
		{ title = "未载", text = "游戏没有说明多诺瓦来自何方，也没有说明她是否效力于某个组织，或效力于哪一个。" },
	},
	chapters = {
		{
			title = "寒水烈酒",
			hint = "把寒水熊怪掉落的一只酒瓶带给学者。",
			text = [=[酒瓶是空的，只剩几滴发光的绿色液体。多诺瓦立刻认出它类似于{link:felwood}费伍德森林{/link}的污泥。线索指向{link:deadwood-furbolgs}死木部族{/link}的营地，又从那里指向{link:irontree-woods}铁木森林{/link}的毒性恐怖。当她把毒液与泉水混合时，毒液失去了致命性，却保留了对饮用者的支配力。现在她明白了{link:winterfall-furbolgs}寒水熊怪{/link}为何守护温泉：他们需要温泉来酿造{link:brewnall-village}烈酒{/link}。]=],
		},
		{
			title = "大酋长",
			hint = "终结指挥寒水熊怪的人。",
			text = [=[多诺瓦说，{link:winterfall-furbolgs}寒水熊怪{/link}从来不是一个好战的部族。只有他们的酋长才可能把他们引上这条路。她并不指望挽回已经发生的事，但她相信，没有了首领，他们不会再继续堕落下去。酋长随身带着一本日志，上面的记号粗糙得她无法辨认。她把它向南送给了{link:kelek-skykeeper}科雷克·望天{/link}，一位熟知{link:felwood}费伍德森林{/link}{link:furbolgs}熊怪{/link}的德鲁伊。]=],
		},
		{
			title = "温泉之源",
			hint = "南行到空气变得浓重、天空变得昏暗的地方。",
			text = [=[多诺瓦不相信温泉仅仅是被大地温暖的。她派一名旅人前往{link:winterspring}冬泉谷{/link}的最南端，那里的空气变得闷热，天空变得昏暗。{link:darkwhisper-gorge}暗语峡谷{/link}和它的恶魔就在那里。多诺瓦如今注视着温泉，留意它们影响的任何新迹象。]=],
		},
	},
	mentions = {
		{ text = "{link:winterspring}冬泉谷{/link}的麻烦！，来自麦吉·贝比罗克" },
		{ text = "{link:winterfall-furbolgs}寒水熊怪{/link}的威胁" },
		{
			text = [=[{link:winterfall-furbolgs}寒水{/link}{link:brewnall-village}烈酒{/link}]=],
		},
		{ text = "堕入腐化" },
		{ text = "神秘的黏液" },
		{ text = "毒性恐怖" },
		{ text = "{link:winterfall-furbolgs}寒水{/link}信使" },
		{ text = "{link:high-chief-winterfall}冬泉酋长{/link}" },
		{ text = "最后的碎片" },
		{ text = "{link:furbolgs}熊怪{/link}酋长的话" },
		{ text = "新的泉水，来自{link:krakle}克拉兰克{/link}" },
		{ text = "奇异的源头" },
		{ text = "人人都知道的秘密" },
		{ text = "维德{link:farmer-ray}雷{/link}药剂" },
		{ text = "坟墓前的会面" },
	},
	bonds = {
		{ id = "high-chief-winterfall", name = "冬泉酋长", note = "她想要阻止的酋长" },
		{ id = "kelek-skykeeper", name = "科雷克·望天", note = "为她解读酋长的日志" },
		{ id = "linken", name = "林克", note = "她的朋友，失去了记忆" },
		{ id = "krakle", name = "克拉兰克", note = "她在安戈洛的朋友" },
	},
})

