			text = [=[赫达琳统治着{link:darkwhisper-gorge}暗语峡谷{/link}的恶魔。她的追随者，赫德琳新信徒、法力追猎者和杀戮者，都以她的名字为名。她们居住在{link:mount-hyjal}海加尔山{/link}北麓，{link:burning-legion}燃烧军团{/link}在那里被击溃，但没有记录说明她们何时到来。学者{link:donova-snowden}多诺瓦·雪山{/link}相信，她们的存在毒害了这片土地，并温暖了遥远北方的温泉。]=],
		},
	},
})

Translate("zhCN", "winterfall-furbolgs", {
	title = "寒水熊怪",
	aliases = { "寒水", "寒水部族" },
	sections = {
		{
			title = "概述",
			text = [=[寒水熊怪是{link:winterspring}冬泉谷{/link}的{link:furbolgs}熊怪{/link}部族。他们原本不是好战的民族，长期以来都是{link:timbermaw-furbolgs}木喉熊怪{/link}的盟友。这一切已经改变。他们的大酋长向他们提出了奇怪的要求，如今他们会袭击任何靠近的人，无论是野兽还是旅人，精灵还是地精。他们在{link:everlook}永望镇{/link}以东的山中有一座村庄，在{link:frostfire-hot-springs}冰火温泉{/link}附近也有营地。]=],
		},
		{
			title = "烈酒",
			text = [=[这种疯狂有其根源。部族的信使穿过{link:timbermaw-hold}木喉要塞{/link}，前往{link:felwood}费伍德森林{/link}的{link:deadwood-furbolgs}死木熊怪{/link}那里，而死木熊怪本身也被邪能腐化逼疯了。他们带回一种绿色的酒，是用{link:irontree-woods}铁木森林{/link}毒性恐怖的毒液酿成的。单独饮用，它会要了他们的命。与温泉的水混合后，它失去了致命性，却保留了效力，饮用者会变得更加高大、更加凶残。这就是寒水熊怪如此凶猛地守护温泉的原因。{link:furbolgs}熊怪{/link}们仍然随身带着灵珠以驱除邪灵，但灵珠并没有把他们从如今的样子中拯救出来。]=],
		},
	},
})

Translate("zhCN", "crystal-of-zin-malor", {
	title = "辛玛洛水晶",
	sections = {
		{
			title = "概述",
			text = [=[辛玛洛水晶是一件能够容纳并驾驭强大奥术之力的圣物。只有真正有资格的人才能驾驭它，也只有少数最强大的法师才有希望做到。它以{link:temple-of-zin-malor}辛玛洛神殿{/link}命名，那座神殿如今已成为{link:azshara}艾萨拉{/link}的一片废墟。在远古时代，{link:lake-kel-theril}凯斯利尔{/link}的上层精灵盗走了它，想要为自己汲取它的力量。在这一尝试中，水晶在一场猛烈的爆炸中碎裂，碎片沉入了湖冰之下。上层精灵受到诅咒，永远留在那里，至今仍在寻找那些碎片。]=],
		},
		{
			title = "重铸",
			text = [=[当今，一位{link:dwarves}矮人{/link}的镐凿破冰层，带上来四块碎片。{link:high-elves}高等精灵{/link}{link:aurora-skycaller}奥萝拉{/link}认出了它们。借助从{link:azshara}艾萨拉{/link}那座废弃神殿中找回的上层精灵神圣典籍，她让水晶恢复了完整。它被展示给一个对旧日罪行心怀悔恨的{link:lake-kel-theril}凯斯利尔{/link}灵魂，那个灵魂得到了安息。水晶永远无法回到它的神殿。{link:starfall-village}坠星村{/link}的{link:wynd-nightchaser}维恩德·夜风{/link}把它送给了{link:darnassus}达纳苏斯{/link}的{link:fandral-staghelm}大德鲁伊范达尔·鹿盔{/link}，后者称赞护送它的人没有试图自己使用它。]=],
		},
	},
})
